// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.POST(options.BaseURL+"/storefront/v1/recommendations/cart", wrapper.GetCartRecommendations)
	router.POST(options.BaseURL+"/storefront/v1/carts", wrapper.CreateCart)
	router.GET(options.BaseURL+"/storefront/v1/carts/:token", wrapper.GetCart)
	router.PUT(options.BaseURL+"/storefront/v1/carts/:token/items", wrapper.UpdateCartItems)
	router.PUT(options.BaseURL+"/storefront/v1/carts/:token/coupon", wrapper.ApplyCoupon)
	router.POST(options.BaseURL+"/storefront/v1/carts/:token/shipping-options", wrapper.GetShippingOptions)
	router.POST(options.BaseURL+"/storefront/v1/carts/:token/payment-intent", wrapper.CreatePaymentIntent)
	router.POST(options.BaseURL+"/storefront/v1/carts/:token/checkout", wrapper.CheckoutCart)
	router.POST(options.BaseURL+"/storefront/v1/wishlists", wrapper.CreateWishlist)
	router.GET(options.BaseURL+"/storefront/v1/wishlists/:token", wrapper.GetWishlist)
	router.PUT(options.BaseURL+"/storefront/v1/wishlists/:token/items", wrapper.ToggleWishlistItem)
	router.POST(options.BaseURL+"/storefront/v1/auth/magic-link", wrapper.RequestMagicLink)
	router.POST(options.BaseURL+"/storefront/v1/auth/session", wrapper.VerifySession)
	router.DELETE(options.BaseURL+"/storefront/v1/account/:token", wrapper.Logout)
	router.GET(options.BaseURL+"/storefront/v1/account/:token", wrapper.GetAccount)
	router.GET(options.BaseURL+"/storefront/v1/account/:token/orders", wrapper.ListAccountOrders)
	router.GET(options.BaseURL+"/storefront/v1/products", wrapper.ListStorefrontProducts)
	router.GET(options.BaseURL+"/storefront/v1/products/:id", wrapper.GetStorefrontProduct)
	router.GET(options.BaseURL+"/storefront/v1/products/:id/recommendations", wrapper.GetStorefrontProductRecommendations)
	router.GET(options.BaseURL+"/storefront/v1/products/:id/reviews", wrapper.ListStorefrontReviews)
	router.POST(options.BaseURL+"/storefront/v1/products/:id/reviews", wrapper.SubmitStorefrontReview)
	router.GET(options.BaseURL+"/storefront/v1/categories", wrapper.ListStorefrontCategories)
	router.GET(options.BaseURL+"/storefront/v1/orders/lookup", wrapper.LookupStorefrontOrder)
	router.GET(options.BaseURL+"/storefront/v1/theme/pages/:slug", wrapper.GetStorefrontTheme)
	router.GET(options.BaseURL+"/storefront/v1/theme/draft/pages/:slug", wrapper.GetStorefrontThemeDraft)
	router.PUT(options.BaseURL+"/storefront/v1/theme/draft/pages/:slug", wrapper.SaveStorefrontThemeDraft)
}

